class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int v) { val = v; }
}

class Solution {
    private Map<Integer, Integer> cnt = new HashMap<>();

    public int pathSum(TreeNode root, int targetSum) {
        cnt.put(0, 1);
        return dfs(root, 0, targetSum);
    }

    private int dfs(TreeNode node, int cur, int target) {
        if (node == null) return 0;
        cur += node.val;
        int total = cnt.getOrDefault(cur - target, 0);
        cnt.put(cur, cnt.getOrDefault(cur, 0) + 1);
        total += dfs(node.left, cur, target) + dfs(node.right, cur, target);
        cnt.put(cur, cnt.get(cur) - 1);
        return total;
    }
}

