        dfs(0);
        return res;
    }

    private void dfs(int i) {
        if (i == digits.length()) {
            res.add(path.toString());
            return;
        }
        for (char ch : T[digits.charAt(i) - '0'].toCharArray()) {
            path.append(ch);
            dfs(i + 1);
            path.deleteCharAt(path.length() - 1);
        }
    }
}

